package local.skyfamily;
import android.content.Context;import android.graphics.*;import android.view.View;import java.util.Locale;
final class DestinationIcon extends View {
 final int kind,color;final Paint pen=new Paint(3);DestinationIcon(Context c,int k,int ink){super(c);kind=k;color=ink;setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);}
 static int kind(String value){String s=value.toLowerCase(Locale.US);if(s.contains("explore")||s.contains("telescope")||s.contains("space")||s.contains("planetarium")||s.contains("sky")||s.contains("northern")||s.startsWith("eso")||s.startsWith("iss")||s.startsWith("nasa"))return 1;if(s.contains("aquarium")||s.contains("fish")||s.contains("kelp")||s.contains("reef")||s.contains("shark")||s.contains("open sea"))return 2;if(s.contains("wildlife")||s.contains("alveus")||s.contains("winnie")||s.contains("zoo")||s.contains("moose")||s.contains("otter")||s.contains("creature"))return 3;if(s.contains("nature")||s.contains("slow tv"))return 4;if(s.contains("weather"))return 5;if(s.contains("camera")||s.contains("beach")||s.contains("harbour"))return 6;if(s.contains("news"))return 7;return 0;}
 protected void onDraw(Canvas c){c.save();c.scale(getWidth()/32f,getHeight()/32f);pen.setColor(color);pen.setStyle(Paint.Style.STROKE);pen.setStrokeWidth(2);pen.setStrokeCap(Paint.Cap.ROUND);pen.setStrokeJoin(Paint.Join.ROUND);if(kind==1){c.save();c.rotate(-25,16,12);c.drawRect(7,8,25,16,pen);c.drawRect(4,6,8,18,pen);c.drawRect(25,10,29,14,pen);c.restore();c.drawLine(17,18,17,28,pen);c.drawLine(17,18,9,28,pen);c.drawLine(17,18,25,28,pen);}else if(kind==2){c.drawOval(new RectF(4,9,23,23),pen);Path tail=new Path();tail.moveTo(23,16);tail.lineTo(29,9);tail.lineTo(29,23);tail.close();c.drawPath(tail,pen);c.drawCircle(9,15,1,pen);c.drawLine(14,9,18,5,pen);}else if(kind==3){c.drawOval(new RectF(8,16,24,28),pen);c.drawOval(new RectF(3,9,9,17),pen);c.drawOval(new RectF(10,3,15,12),pen);c.drawOval(new RectF(18,3,23,12),pen);c.drawOval(new RectF(25,9,30,17),pen);}else if(kind==4){Path leaf=new Path();leaf.moveTo(5,27);leaf.cubicTo(2,6,18,3,28,4);leaf.cubicTo(29,20,20,29,5,27);c.drawPath(leaf,pen);c.drawLine(4,29,23,10,pen);c.drawLine(12,21,12,13,pen);c.drawLine(16,17,23,17,pen);}else if(kind==5){c.drawArc(new RectF(3,12,18,26),90,180,false,pen);c.drawArc(new RectF(9,6,25,24),180,180,false,pen);c.drawArc(new RectF(20,13,30,25),-90,180,false,pen);c.drawLine(10,25,25,25,pen);}else if(kind==6){c.drawRoundRect(new RectF(3,9,29,27),3,3,pen);c.drawCircle(16,18,6,pen);c.drawRect(9,5,20,9,pen);}else{c.drawRect(4,5,28,28,pen);c.drawRect(8,9,15,16,pen);c.drawLine(19,10,24,10,pen);c.drawLine(19,15,24,15,pen);c.drawLine(8,21,24,21,pen);c.drawLine(8,25,24,25,pen);}c.restore();}
}
